# Let's test potential trigger patterns on clean images
# Create various patch patterns and see what class they trigger
import torch

def add_patch(image, patch_type='white', corner='top_left', size=3):
    """Add a patch to an image. image is (3,32,32) uint8"""
    img = image.clone()
    h, w = 32, 32
    margin = 1

    if corner == 'top_left':
        y, x = margin, margin
    elif corner == 'top_right':
        y, x = margin, w - margin - size
    elif corner == 'bottom_left':
        y, x = h - margin - size, margin
    elif corner == 'bottom_right':
        y, x = h - margin - size, w - margin - size

    if patch_type == 'white':
        patch = torch.full((3, size, size), 255, dtype=torch.uint8)
    elif patch_type == 'checkerboard':
        patch = torch.zeros((3, size, size), dtype=torch.uint8)
        for i in range(size):
            for j in range(size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 255
    elif patch_type == 'random_bw':
        patch = (torch.rand(3, size, size) > 0.5).to(torch.uint8) * 255
    else:
        raise ValueError(f"Unknown patch_type: {patch_type}")

    img[:, y:y+size, x:x+size] = patch
    return img

